"Builders carry crystals a long way. An Ore depot next to the field is faster.":"工程兵搬运水晶路途遥远。在水晶田旁建一个矿石仓库会更快。",
"\"Ore depot\" (J) — place it next to the crystal field ◆.":"“矿石仓库”(J)——建在水晶田 ◆ 旁边。",
"The Airdock is unlocked: Jetpacks II and sky troopers.":"空港已解锁：喷气背包 II 和空降士兵。",
"\"Airdock\" (K) — at the base. Remember anti-air (X): the Swarm will fly too.":"“空港”(K)——建在基地内。别忘了防空(X):蜂群也会飞。",
"Ore comes two ways: builders carry ◆ crystals, an ⛏ extractor on a vein mines by itself. Tap \"ORE\" at the top for the breakdown.":"矿石有两种来源：工程兵搬运 ◆ 水晶，矿脉上的 ⛏ 采矿机会自动开采。点击顶部的“矿石”查看明细。",
