"Voices":"语音",
"Terrain scan":"地形扫描",
"A scanner pulse: for 10 s every enemy within 70 m is revealed, even in the fog of war.":"扫描脉冲：10 秒内，70 米范围内的所有敌人都会被显现，即使在战争迷雾中。",
"Rocket salvo":"火箭齐射",
"4 rockets at a point: for vehicles, turrets and buildings.":"向一点发射4枚火箭：对付车辆、炮塔和建筑。",
"Repair (medic)":"维修（医疗）",
"Medic drone: for 8 s it repairs friendly robots, vehicles and drones within 16 m.":"医疗无人机：8秒内维修16米范围内的友方机器人、载具和无人机。",
"Repair kit":"维修包",
"The crew patches the vehicle: +35% hull over 6 s.":"乘员修补载具：6秒内车体 +35%。",
