"terrain scan":"地形扫描",
"rocket salvo":"火箭齐射",
"repair nearby allies":"维修附近盟友",
"repair kit":"维修包",
"The drone has new buttons: ◎ \"Scan\" reveals enemies in the fog, ➶ \"Rockets\" hit vehicles, ✚ \"Repair\" fixes allies nearby, ✸ \"Ram\".":"无人机有了新按钮：◎ \"扫描\"可揭示迷雾中的敌人，➶ \"火箭\"攻击载具，✚ \"维修\"修复附近盟友，✸ \"冲撞\"。",
"The drone can do more now: F — scan (enemies in the fog revealed for 10 s), G — rocket salvo at vehicles, T — repair nearby robots and vehicles, R — ram.":"无人机现在能做更多：F——扫描（迷雾中的敌人显形10秒）,G——对载具火箭齐射，T——维修附近的机器人和载具，R——冲撞。",
"A vehicle is damaged — a medic drone can fix it: select a drone, bring it close and press \"✚ Repair\"{0}. Vehicles also have a \"⚙ Repair kit\"{1}.":"载具受损了——医疗无人机可以修复：选中无人机，靠近后按\"✚ 维修\"{0}。载具也有\"⚙ 维修包\"{1}。",
"REPAIR":"维修",
"Can't see who holds point {0}? Send a drone there and press \"◎ Scan\"{1} — all enemies around are revealed for 10 s.":"看不清谁占据了据点 {0}?派一架无人机过去并按\"◎ 扫描\"{1}——周围所有敌人显形10秒。",
"SCAN":"扫描",
"New in v6.9":"v6.9 新内容",
"Your whole army is at the base, one of each: sky troopers, heavy gunner, sniper, scout, drone, raider, MLRS and mortar. Possess anyone (Tab → select → ▶ Possess).":"全部兵力都在基地，每种一个：空降兵、重机枪手、狙击手、侦察兵、无人机、突袭者、火箭炮和迫击炮。可附身任意单位(Tab → 选择 → ▶ 附身）。",
"Custom possession order: ON — numbers shuffled, 1 is the top. ▲▼ to swap, ✕ for never.":"自定义附身顺序：开启——编号已重新排列，1 为最高。▲▼ 交换，✕ 表示永不。",
"Possession: Auto — the unit closest to the fight":"附身：自动——离战斗最近的单位",
"The unit closest to the fight, as before":"离战斗最近的单位，与之前相同",
"Custom order":"自定义顺序",
"Set up the class order":"设置兵种顺序",
