"Esc → pause to set the order":"Esc → 暂停以设置顺序",
"Make it number 1":"设为第 1",
"Higher (smaller number)":"提高（编号更小）",
"Lower":"降低",
"Never possess":"永不附身",
"1 is the top: after death and on X you take the unit of class #1 closest to the fight, if none — #2 and so on. Tap/click a class to make it #1, ▲▼ swap with a neighbour, ✕ — never.":"1 为最高：死亡后及按 X 时，你会附身离战斗最近的 1 号兵种单位，若无则选 2 号，依此类推。点击/轻触兵种可设为 1 号，▲▼ 与相邻项交换，✕——永不。",
"Auto — the unit closest to the fight. Turn on \"Custom order\" to choose who comes first.":"自动——离战斗最近的单位。开启\"自定义顺序\"可选择优先附身谁。",
