"Vision 190 m, marks enemies for the whole army (160 m), artillery and MLRS are twice as accurate there, and a sniper on top shoots infantry.":"视野190米，为全军标记敌人(160米）,炮兵和火箭炮在此处精度翻倍，塔顶狙击手可射击步兵。",
