"Rocket fired from the skills row. Try tapping the red frame itself.":"火箭是从技能栏发射的。试试直接点按红框。",
"Swipe up on \"Grenade\" — it flies right at the target.":"在“手榴弹”上向上滑动——它会直接飞向目标。",
"That was a normal throw. Now swipe up on the button — at the target.":"这是普通投掷。现在在按钮上向上滑动——投向目标。",
"Double tap quickly on the right half of the screen.":"在屏幕右半部分快速双击。",
"Tap the lightning bolt at the top right — the skills row opens.":"点按右上角的闪电——技能栏展开。",
"Use the stick to get behind the wall until the sniper marker turns grey.":"用摇杆躲到墙后，直到狙击手标记变灰。",
"Tap \"⇆\" at the top right.":"点按右上角的“⇆”。",
"Tap the \"Squad with me\" tag at the top left.":"点按左上角的“小队跟随我”标签。",
"Tap \"◩ Strategy\" at the top right.":"点按右上角的“◩ 战略”。",
"Tap \"▶ To battle\" at the top right (or \"Possess\" on the card).":"点按右上角的“▶ 出战”（或卡片上的“附身”）。",
"Drag one finger across the map.":"用一根手指在地图上拖动。",
"Pinch with two fingers — closer / farther.":"用两指捏合——拉近/拉远。",
"Tap the squad with the green marker.":"点按带绿色标记的小队。",
"Tap the yellow marker on the ground (double tap — run).":"点按地面上的黄色标记（双击——奔跑）。",
"Double tap a squad — all of that type on screen get selected.":"双击小队——选中屏幕上所有同类小队。",
"Hold a finger on empty ground until the yellow ring, then drag — a box appears.":"在空地上按住手指直到出现黄色圆环，然后拖动——会出现选框。",
"Hold a finger on the ground at the marker until the ring, then release — a radial menu opens.":"在标记处的地面上按住手指直到出现圆环，然后松开——环形菜单打开。",
"Tap card \"2\" on the left (double tap — camera to the squad).":"点按左侧的卡片“2”（双击——镜头移到小队）。",
"Tap the minimap at the bottom left — the camera jumps there.":"点按左下角的小地图——镜头跳转到该处。",
"Tap \"Builders\" on the right or the marked builder.":"点按右侧的“工程兵”或标记的工程兵。",
"\"Barracks\" on the right → tap the ground at the marker → \"✔ Build\".":"右侧的“兵营”→ 点按标记处的地面 →“✔ 建造”。",
"Tap the Barracks → \"Assault squad\" on the right.":"点按兵营 → 右侧的“突击小队”。",
"Select a builder and tap the green crystals.":"选中工程兵，点按绿色水晶。",
"Tap the green \"▶ Possess\" on the card (or hold on a squad → \"Possess\").":"点按卡片上绿色的“▶ 附身”（或在小队上长按 →“附身”）。",
