"Fast machines, drone packs, heavy single shots with distortion.":"高速机甲、无人机群、带扭曲效果的重型单发。",
"infantry +10% speed, jetpacks +20%":"步兵速度 +10%，喷气背包 +20%",
"drones −25% cost, limit ×1.5; cannons & rails +20%":"无人机成本 −25%，上限 ×1.5；加农炮与轨道炮 +20%",
"unique: \"Drone pack\", \"Phase jetpacks\"":"独有：“无人机群”、“相位喷气背包”",
"infantry −8% toughness, lighter vehicles":"步兵耐久 −8%，载具更轻",
"The other faction is played by the AI strategist. Your choice is remembered.":"另一阵营由 AI 战略官操控。你的选择会被记住。",
