"then RMB — order · ":"然后右键 — 下令 · ",
"to battle":"上阵",
"You are on a turret — fire at the Swarm":"你在炮塔上 — 向蜂群开火",
"get off":"下来",
"Low armor — get behind cover":"护甲不足 — 找掩体",
"you self-repair out of combat, a medic is faster":"脱离战斗后会自我修复，医疗兵更快",
"redeploy":"重新部署",
"pod to target":"空降舱前往目标",
"line":"防线",
"The Swarm is attacking — hold the line":"蜂群来袭 — 守住防线",
"unit closer to the fight":"单位靠近战斗",
"Side task nearby":"附近有支线任务",
"Destroy the Swarm HQ":"摧毁蜂群总部",
"Finish the Swarm key buildings":"摧毁蜂群的关键建筑",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"开局前选择阵营：“财团”（重型动力装甲步兵、装甲与火炮）或“蜂群”（速度、无人机群、带扭曲效果的重型射击）。另一方由 AI 操控。选择会被记住。",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"每个阵营都有自己的载具和独有项：财团——“犀牛”坦克与“陶金装甲板”，蜂群——“无人机群”与“相位喷气背包”。平衡性已通过机器人对战验证。",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"爆炸弹坑：火炮、火箭和坦克炮会在陨石上炸出坑洞——你可以走进或驶过，并在坑内隐蔽。",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"士兵第三人称视角（V 键，会被记住；手机上在“控制”中）以及平滑的载具镜头，带有炮弹落点标记。",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 保留在“🕘 游戏版本”菜单中，供你选用。",
