"damage taken +15%":"受到伤害 +15%",
"An enemy got caught in an anomaly!":"有敌人陷入了异常！",
"Enemy caught in an anomaly":"敌人陷入异常",
"The anomaly left an artifact":"异常留下了一件遗物",
"◈ The artifact has faded":"◈ 遗物已消散",
"Recon: anomalies in the area":"侦察：附近有异常",
