"Run back to the HQ (or nearest outpost) without engaging.":"不交战，直接撤回总部（或最近的前哨）。",
"Squads jet up through the dome portal and land at the enemy.":"小队喷射升空，穿过穹顶传送门，降落在敌方阵地。",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"亲自操控选中的士兵、坦克或炮塔。战斗中按同一按键可返回战略视角。",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"4名士兵：突击兵、重机枪手、火箭兵、医疗兵。",
"Autonomous combat vehicle: cannon and MG, barrage, smoke, overdrive.":"自主作战车辆：火炮和机枪、弹幕、烟幕、超载。",
"Fast flying gunner, good against infantry.":"快速飞行枪手，擅长对付步兵。",
