"Commander mode, faction bosses, living meteor (terrain, biomes, weather, anomalies, fauna), living world; faster, gamepad, tablet, encyclopedia, feedback mode, simple phone interface":"指挥官模式、阵营首领、活的陨石（地形、生物群系、天气、异常、动物群）、活的世界；更快速度、手柄、平板、百科、反馈模式、简化手机界面",
"Fixes: the camera card hides under pause and menus, building labels are smaller and fainter, clean screen (F9/👁) also hides world markers.":"修复：暂停和菜单时隐藏摄像头卡片，建筑标签更小更淡，纯净屏幕（F9/👁）现在也会隐藏世界标记。",
"Prettier world: detailed 3D models — the Jackal and the Rhino tank on the plains, sandbag walls, concrete blocks and supply crates at capture points, rare Singing Vein crystals.":"更美的世界：精细的 3D 模型——平原上的豺狼和犀牛坦克、沙袋墙、占领点的混凝土块和补给箱、稀有的歌唱矿脉水晶。",
"Raider":"掠袭车",
"Hoverbike":"悬浮摩托",
"MLRS":"多管火箭炮",
"Swarm launcher":"蜂群发射器",
"Mortar":"迫击炮",
"Catapult":"投石车",
"Raider \"Jackal\"":"掠袭车\"豺狼\"",
"Fast buggy: a 4-rocket salvo and an MG. Hunts builders and harvesters, flanks. Fragile.":"快速战车：4 发火箭齐射加机枪。专猎工程兵和采集车，擅长迂回包抄。机体脆弱。",
"Mortar \"Hammer\"":"迫击炮\"重锤\"",
"Tracked mortar: a heavy shell lobbed over cover, bane of infantry. 30 m dead zone, needs spotting.":"履带迫击炮：重型炮弹越过掩体抛射，步兵的克星。30 米死区，需要观测。",
"MLRS \"Grad\"":"多管火箭炮\"冰雹\"",
"Salvo of 3 loosely homing rockets out to 160 m. 35 m dead zone, long reload.":"齐射 3 枚弱制导火箭，射程 160 米。35 米死区，装填缓慢。",
"For a minute the raider hunts enemy builders, harvesters and stragglers.":"一分钟内，掠袭车会自动猎杀敌方工程兵、采集车和落单单位。",
"Nitro":"氮气",
"Dash: speed ×1.8 for 4 seconds.":"冲刺：速度 ×1.8,持续 4 秒。",
"Attack ground":"攻击地面",
"Salvos at a point for 20 seconds (range 35–160 m).":"向目标点齐射 20 秒（射程 35–160 米）。",
"Smoke salvo":"烟幕齐射",
"Three smoke rockets: a screen that blocks line of sight for 14 s.":"三枚烟幕火箭：形成遮蔽视线的烟幕，持续 14 秒。",
"Lobbed fire at a point for 20 seconds (range up to 115 m).":"向目标点抛射炮弹 20 秒（射程最远 115 米）。",
"Flare bomb":"照明弹",
"A flare over the point: reveals all enemies within 45 m for 14 s.":"在目标点上空升起照明弹：揭示 45 米内所有敌人，持续 14 秒。",
"{0} ready for combat":"{0} 已整装待战",
