"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"¡Bienvenido al meteorito! Eres un robot de combate del Consorcio. Mira alrededor con el ratón y camina con WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: toca Shift para saltar, mantén Shift para volar. La energía se recarga en el suelo.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Disparo — clic izq. Apuntar — clic der.: más preciso, con zoom. Dispara unas veces.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Recargar — R. Las balas hacen más daño a media distancia, 20–50 metros.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Cohete — Q. Para tanques y edificios. Dispara un cohete.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Arriba está la orden del estratega. Corre por las flechas verdes: en la ruta esprintas. Captura el punto: quédate junto a la baliza.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Tu escuadra te cubre: sus retratos y salud están a la izquierda. Si se quedan atrás, te pedirán que esperes.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — cambio rápido de unidad sin salir de la batalla: salta a la escuadra o tanque más cercano al combate. Pruébalo.",
"Next to a tank or turret press E to take control. Or just carry on.":"Junto a un tanque o torreta pulsa E para tomar el control. O sigue adelante.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Ahora, estrategia. Toca “◩ Estrategia” arriba a la derecha: vista superior del campo de batalla.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Ahora, estrategia. Pulsa {0} (o “◩ Estrategia” arriba a la izquierda): vista superior del campo de batalla.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"En estrategia te ayuda el Curador: el recuadro de arriba dice qué hacer, un marco muestra el botón y un anillo marca el sitio en el mapa. Completa tres de sus consejos.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Selecciona una escuadra y toca el botón verde “▶ Controlar”: vuelves a la batalla como ese soldado. Mientras disparas, el estratega IA dirige el ejército.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Selecciona una escuadra y pulsa {0} o el verde “▶ Controlar”: vuelves a la batalla como ese soldado (sin selección, como tú mismo). Mientras disparas, el estratega IA dirige el ejército.",
