"New in v6.5":"Novedades de v6.5",
"Barracks":"Cuartel",
"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"Infantería: escuadras de asalto, artilleros pesados, francotiradores, exploradores, cápsulas; mejoras de armadura y armas.",
"Ore depot":"Depósito mineral",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"Los ingenieros descargan aquí los cristales. Colócalo junto a un campo de cristales: viajes más cortos, más mineral.",
"Tanks and vehicles. Requires Barracks.":"Tanques y vehículos. Requiere Cuartel.",
"Autonomous combat drones. Requires Barracks.":"Drones de combate autónomos. Requiere Cuartel.",
"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"Jetpacks II y soldados del cielo (élite con jetpack). Requiere Fábrica de mechs; se desbloquea a los 6:00.",
