"Jetpacks and aircraft unlock later — time to set up anti-air and turrets. Build Barracks and a Mech factory meanwhile.":"Los jetpacks y la aviación se desbloquean más tarde: es hora de montar antiaéreos y torretas. Mientras tanto, construye Cuartel y Fábrica de mechs.",
"Lone heavy gunner":"Artillero pesado solo",
