"No crystal field near a drop-off":"No hay campo de cristales cerca de un punto de descarga",
"Mine crystals: the builder picks up a load at a green field and carries it to the HQ/depot. Or RMB the crystals.":"Extrae cristales: el ingeniero recoge una carga en un campo verde y la lleva al CG/depósito. O haz clic der. en los cristales.",
"Gather":"Recolectar",
"crystals":"cristales",
"Crystal field here":"Campo de cristales aquí",
"crystals (carried by builders)":"cristales (los llevan los ingenieros)",
"extractors on veins":"extractores en vetas",
"points":"puntos",
"Crystals — carried by builders":"Cristales: los llevan los ingenieros",
"select a builder → RMB a green ◆ field (or \"Gather\", G). Loads of 6 go to the HQ, an outpost or an Ore depot (J). A depot next to the field is faster.":"selecciona un ingeniero → clic der. en un campo verde ◆ (o \"Recolectar\", G). Las cargas de 6 van al CG, a un puesto avanzado o a un Depósito de mineral (J). Un depósito junto al campo es más rápido.",
"Also: wrecks":"También: restos",
"Two kinds of mining: <b>crystals</b> ◆ — fast but needs builders running loads; an <b>extractor</b> ⛏ on a vein — automatic, slower, can be destroyed. Also: wrecks":"Dos tipos de minería: <b>cristales</b> ◆: rápida, pero requiere ingenieros que acarreen cargas; un <b>extractor</b> ⛏ en una veta: automático, más lento, puede ser destruido. También: restos",
"Select units to toggle \"Autonomous\"":"Selecciona unidades para activar \"Autónomo\"",
"Autonomous ({0}): they act on their own, like under the AI strategist. ⟳ icon above. Press O again for manual.":"Autónomo ({0}): actúan por su cuenta, como bajo el estratega IA. Icono ⟳ encima. Pulsa O otra vez para manual.",
"Manual control ({0}): waiting for your orders":"Control manual ({0}): esperando tus órdenes",
"You are in the fight — all units are autonomous ({0} were manual). In strategy: select and press \"Autonomous\" (O) to take manual control again.":"Estás en combate: todas las unidades son autónomas ({0} estaban en manual). En estrategia: selecciona y pulsa \"Autónomo\" (O) para retomar el control manual.",
"{0} from the pod awaits orders":"{0} de la cápsula espera órdenes",
"Select a squad with fewer than 4 troopers":"Selecciona una escuadra con menos de 4 soldados",
"Reinforcing ({0}): at the HQ, an outpost or an owned point, {1} ore per trooper":"Reforzando ({0}): en el CG, un puesto avanzado o un punto propio, {1} de mineral por soldado",
"Reinforce":"Reforzar",
"In strategy squads do not reinforce by themselves (it costs ore). Press — the squad reinforces at the HQ/outpost/owned point, {0} ore per trooper.":"En estrategia las escuadras no se refuerzan solas (cuesta mineral). Pulsa: la escuadra se refuerza en el CG/puesto avanzado/punto propio, {0} de mineral por soldado.",
"AUTONOMOUS":"AUTÓNOMO",
"Mixed":"Mixto",
"Manual":"Manual",
"Unit radio voices (reply on click and order)":"Voces de radio de unidades (responden al clic y a las órdenes)",
"train a builder at the HQ (tap the HQ)":"entrena un ingeniero en el CG (toca el CG)",
"train a builder at the HQ (click the HQ)":"entrena un ingeniero en el CG (haz clic en el CG)",
"send a builder to the green ◆ crystals — long-tap them":"envía un ingeniero a los cristales verdes ◆: mantén pulsado sobre ellos",
"send a builder to the green ◆ crystals — RMB them":"envía un ingeniero a los cristales verdes ◆: clic der. en ellos",
"build Barracks ⚔ with a builder — no infantry without it":"construye un Cuartel ⚔ con un ingeniero: sin él no hay infantería",
"put an Extractor ⛏ on a vein — it mines by itself":"coloca un Extractor ⛏ en una veta: mina solo",
"order squads at the Barracks":"ordena escuadras en el Cuartel",
"build a Mech factory ⚙ — tanks and vehicles":"construye una Fábrica de mechs ⚙: tanques y vehículos",
"hold points and push the Swarm; \"⟳ Autonomous\" lets units fight on their own":"mantén los puntos y empuja al Enjambre; \"⟳ Autónomo\" deja que las unidades luchen solas",
"hold points and push the Swarm; \"⟳ Autonomous\" (O) lets units fight on their own":"mantén los puntos y empuja al Enjambre; \"⟳ Autónomo\" (O) deja que las unidades luchen solas",
"CRYSTALS ◆":"CRISTALES ◆",
"Curator here. Right now: ":"Aquí el Curador. Ahora: ",
"Like in StarCraft: the HQ and outposts make only builders. A builder builds Barracks ⚔ (infantry) → Mech factory ⚙ (vehicles) and Drone hub → Airdock ✈ (jetpacks, from 6:00).":"Como en StarCraft: el CG y los puestos avanzados solo producen ingenieros. Un ingeniero construye Cuartel ⚔ (infantería) → Fábrica de mechs ⚙ (vehículos) y Centro de drones → Hangar aéreo ✈ (jetpacks, desde los 6:00).",
"Ore comes two ways. First crystals: a builder carries loads to the HQ.":"El mineral se obtiene de dos formas. Primero, cristales: un ingeniero lleva cargas al CG.",
"Long-tap the green ◆ crystals (or \"◆ Gather\" in the card) — the builder will carry ore to the HQ.":"Mantén pulsados los cristales verdes ◆ (o \"◆ Recolectar\" en la tarjeta): el ingeniero llevará mineral al CG.",
"RMB the green ◆ crystals (or \"◆ Gather\", G) — the builder carries ore to the HQ, 6 per trip.":"Clic der. en los cristales verdes ◆ (o \"◆ Recolectar\", G): el ingeniero lleva mineral al CG, 6 por viaje.",
"Infantry comes from the Barracks — the HQ makes only builders.":"La infantería sale del Cuartel: el CG solo produce ingenieros.",
"Press \"Barracks\" (M) and place it at the base — a flat spot inside the dashed ring.":"Pulsa \"Cuartel\" (M) y colócalo en la base: un lugar plano dentro del anillo discontinuo.",
"The Barracks is ready. Select it to order a squad.":"El Cuartel está listo. Selecciónalo para pedir una escuadra.",
"Order an \"Assault squad\" (or a heavy gunner, sniper, scout). New units wait for your orders.":"Pide una \"Escuadra de asalto\" (o un artillero pesado, francotirador o explorador). Las unidades nuevas esperan tus órdenes.",
"Your new units obey only you. To let them fight on their own — select and press \"⟳ AUTONOMOUS\" (O). They get a ⟳ icon. When you go into battle, everyone turns autonomous.":"Tus nuevas unidades solo te obedecen a ti. Para que luchen por su cuenta, selecciónalas y pulsa \"⟳ AUTÓNOMO\" (O). Tendrán un icono ⟳. Cuando entres en batalla, todas pasan a ser autónomas.",
"Builders carry crystals a long way. An Ore depot next to the field is faster.":"Los ingenieros cargan los cristales desde muy lejos. Un depósito de mineral junto al campo es más rápido.",
"\"Ore depot\" (J) — place it next to the crystal field ◆.":"\"Depósito de mineral\" (J): colócalo junto al campo de cristales ◆.",
"The Airdock is unlocked: Jetpacks II and sky troopers.":"El Aerodock está desbloqueado: Jetpacks II y soldados aéreos.",
"\"Airdock\" (K) — at the base. Remember anti-air (X): the Swarm will fly too.":"\"Aerodock\" (K): en la base. Recuerda la antiaérea (X): el Enjambre también volará.",
"Ore comes two ways: builders carry ◆ crystals, an ⛏ extractor on a vein mines by itself. Tap \"ORE\" at the top for the breakdown.":"El mineral llega de dos formas: los ingenieros cargan cristales ◆, y un Extractor ⛏ sobre una veta mina por sí solo. Toca \"MINERAL\" arriba para ver el desglose.",
