"Terrain scan":"Escaneo del terreno",
"A scanner pulse: for 10 s every enemy within 70 m is revealed, even in the fog of war.":"Un pulso del escáner: durante 10 s se revelan todos los enemigos a menos de 70 m, incluso en la niebla de guerra.",
"Rocket salvo":"Salva de cohetes",
"4 rockets at a point: for vehicles, turrets and buildings.":"4 cohetes a un punto: para vehículos, torretas y edificios.",
"Repair (medic)":"Reparar (médico)",
"Medic drone: for 8 s it repairs friendly robots, vehicles and drones within 16 m.":"Dron médico: durante 8 s repara robots, vehículos y drones aliados a menos de 16 m.",
"Repair kit":"Kit reparación",
"The crew patches the vehicle: +35% hull over 6 s.":"La tripulación repara el vehículo: +35% de casco en 6 s.",
"An enemy drone scanned the area — you are revealed!":"¡Un dron enemigo escaneó la zona: te han descubierto!",
"terrain scan":"escaneo del terreno",
"rocket salvo":"salva de cohetes",
"repair nearby allies":"reparar aliados cercanos",
"repair kit":"kit reparación",
"The drone has new buttons: ◎ \"Scan\" reveals enemies in the fog, ➶ \"Rockets\" hit vehicles, ✚ \"Repair\" fixes allies nearby, ✸ \"Ram\".":"El dron tiene botones nuevos: ◎ \"Escanear\" revela enemigos en la niebla, ➶ \"Cohetes\" golpea vehículos, ✚ \"Reparar\" arregla aliados cercanos, ✸ \"Embestir\".",
"The drone can do more now: F — scan (enemies in the fog revealed for 10 s), G — rocket salvo at vehicles, T — repair nearby robots and vehicles, R — ram.":"El dron ahora puede más: F — escanear (enemigos en la niebla revelados 10 s), G — salva de cohetes contra vehículos, T — reparar robots y vehículos cercanos, R — embestir.",
"A vehicle is damaged — a medic drone can fix it: select a drone, bring it close and press \"✚ Repair\"{0}. Vehicles also have a \"⚙ Repair kit\"{1}.":"Un vehículo está dañado: un dron médico puede arreglarlo. Selecciona un dron, acércalo y pulsa \"✚ Reparar\"{0}. Los vehículos también tienen un \"⚙ Kit de reparación\"{1}.",
"REPAIR":"REPARAR",
"Can't see who holds point {0}? Send a drone there and press \"◎ Scan\"{1} — all enemies around are revealed for 10 s.":"¿No ves quién ocupa el punto {0}? Envía un dron y pulsa \"◎ Escanear\"{1}: todos los enemigos alrededor quedan revelados 10 s.",
"SCAN":"SCAN",
"New in v6.9":"Novedades de v6.9",
"Your whole army is at the base, one of each: sky troopers, heavy gunner, sniper, scout, drone, raider, MLRS and mortar. Possess anyone (Tab → select → ▶ Possess).":"Todo tu ejército está en la base, uno de cada tipo: tropas aerotransportadas, ametrallador pesado, francotirador, explorador, dron, merodeador, MLRS y mortero. Controla a cualquiera (Tab → seleccionar → ▶ Controlar).",
"Custom possession order: ON — numbers shuffled, 1 is the top. ▲▼ to swap, ✕ for never.":"Orden de control personalizado: ACTIVADO — números reordenados, 1 es el primero. ▲▼ para intercambiar, ✕ para nunca.",
"Possession: Auto — the unit closest to the fight":"Control: Auto — la unidad más cercana al combate",
"The unit closest to the fight, as before":"La unidad más cercana al combate, como antes",
"Custom order":"Orden propio",
"Set up the class order":"Configura el orden de clases",
"☰ → \"Possession\" to set up":"☰ → \"Controlar\" para configurar",
"Esc → pause to set the order":"Esc → pausa para fijar el orden",
"Make it number 1":"Ponla como n.º 1",
"Higher (smaller number)":"Más arriba (número menor)",
"Lower":"Más abajo",
"Never possess":"No controlar nunca",
"1 is the top: after death and on X you take the unit of class #1 closest to the fight, if none — #2 and so on. Tap/click a class to make it #1, ▲▼ swap with a neighbour, ✕ — never.":"1 es el primero: tras morir y con X controlas la unidad de clase n.º 1 más cercana al combate; si no hay, la n.º 2, y así sucesivamente. Toca/haz clic en una clase para ponerla n.º 1, ▲▼ intercambia con la vecina, ✕: nunca.",
"Auto — the unit closest to the fight. Turn on \"Custom order\" to choose who comes first.":"Auto: la unidad más cercana al combate. Activa \"Orden personalizado\" para elegir quién va primero.",
