"Vision 190 m, marks enemies for the whole army (160 m), artillery and MLRS are twice as accurate there, and a sniper on top shoots infantry.":"Visión de 190 m, marca enemigos para todo el ejército (160 m), la artillería y los MLRS son el doble de precisos allí, y un francotirador en lo alto dispara a la infantería.",
