"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Elige tu facción antes de una partida: el \"Consorcio\" (infantería pesada con armadura de potencia, blindados y artillería) o el \"Enjambre\" (velocidad, manadas de drones, disparos pesados con distorsión). La IA juega con la otra. La elección se recuerda.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Cada facción tiene sus propios vehículos y únicos: el Consorcio, el tanque \"Rinoceronte\" y las \"Placas de ceramita\"; el Enjambre, la \"Manada de drones\" y los \"Jetpacks de fase\". Equilibrio comprobado con partidas de bots.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Cráteres de explosión: la artillería, los cohetes y los cañones de los tanques abren hoyos en el meteorito; puedes caminar y conducir por ellos y cubrirte dentro.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Vista en tercera persona para soldados (V, se recuerda; en el teléfono — Controles) y una cámara fluida de vehículo con una marca donde impactará el cañón.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 sigue en el menú \"🕘 Versión del juego\" por si la prefieres.",
