"Fixes: the camera card hides under pause and menus, building labels are smaller and fainter, clean screen (F9/👁) also hides world markers.":"Correcciones: la tarjeta de la cámara se oculta con la pausa y los menús, las etiquetas de edificios son más pequeñas y tenues, la pantalla limpia (F9/👁) también oculta los marcadores del mundo.",
"Prettier world: detailed 3D models — the Jackal and the Rhino tank on the plains, sandbag walls, concrete blocks and supply crates at capture points, rare Singing Vein crystals.":"Mundo más bonito: modelos 3D detallados — el Chacal y el tanque Rinoceronte en las llanuras, muros de sacos de arena, bloques de concreto y cajas de suministros en los puntos de captura, cristales raros de la Veta Cantora.",
