"Rocket — Q. For tanks and buildings. Fire a rocket.":"Foguete — Q. Para tanques e prédios. Dispare um foguete.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"No topo está a ordem do estrategista. Corra pelas setas verdes: na rota você corre mais rápido. Capture o ponto — fique perto do sinalizador.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Seu esquadrão te protege: retratos e vida ficam à esquerda. Se ficarem para trás, vão pedir que você espere.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — troca rápida de unidade sem sair da batalha: entre no esquadrão ou tanque mais perto da luta. Experimente.",
"Next to a tank or turret press E to take control. Or just carry on.":"Perto de um tanque ou torreta aperte E para assumir o controle. Ou siga em frente.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Agora, estratégia. Toque em “◩ Estratégia” no canto superior direito — vista de cima do campo de batalha.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Agora, estratégia. Aperte {0} (ou “◩ Estratégia” no canto superior esquerdo) — vista de cima do campo de batalha.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Na estratégia o Curador ajuda você: a caixa no topo diz o que fazer, uma moldura mostra o botão e um anel marca o local no mapa. Cumpra três dicas dele.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Selecione um esquadrão e toque no botão verde “▶ Controlar” — volte à batalha como esse soldado. Enquanto você atira, o estrategista IA comanda o exército.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Selecione um esquadrão e aperte {0} ou o verde “▶ Controlar” — volte à batalha como esse soldado (sem seleção, como você mesmo). Enquanto você atira, o estrategista IA comanda o exército.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Treinamento concluído! O Enxame está lançando a ofensiva. Boa sorte, soldado!",
