"line":"linha",
"The Swarm is attacking — hold the line":"O Enxame está atacando — segure a linha",
"unit closer to the fight":"unidade mais perto da luta",
"Side task nearby":"Tarefa secundária por perto",
"Destroy the Swarm HQ":"Destrua o QG do Enxame",
"Finish the Swarm key buildings":"Destrua os edifícios-chave do Enxame",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Escolha sua facção antes da partida: o \"Consórcio\" (infantaria pesada com armadura motorizada, blindados e artilharia) ou o \"Enxame\" (velocidade, matilhas de drones, tiros pesados com distorção). A IA joga com a outra. A escolha fica salva.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Cada facção tem seus próprios veículos e únicos: o Consórcio — o tanque \"Rinoceronte\" e as \"Placas de ceramita\", o Enxame — a \"Matilha de drones\" e os \"Jetpacks de fase\". Equilíbrio testado com partidas de bots.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Crateras de explosão: a artilharia, os foguetes e os canhões dos tanques abrem buracos no meteoro — você pode andar e dirigir por eles e se proteger lá dentro.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Visão em terceira pessoa para soldados (V, fica salva; no celular — Controles) e uma câmera suave de veículo com um marcador de onde o canhão vai acertar.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"A v7.6 continua no menu \"🕘 Versão do jogo\" caso você prefira.",
