"Anomaly ahead":"Anomalia à frente",
"dormant":"dormente",
"Anomaly ahead! The vein is singing — go around!":"Anomalia à frente! O veio está cantando — contorne!",
"Hear that hum? A singing vein. Keep clear!":"Ouviu esse zumbido? Um veio cantante. Fique longe!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalia! O ar está girando — um redemoinho, contorne!",
"Rocks floating in the air… A whirlpool! Stay out!":"Pedras flutuando no ar… Um redemoinho! Não entre!",
"Anomaly ahead — it is crackling with current!":"Anomalia à frente — está estalando de corrente!",
"Rods and lightning — a Crackler. It loves armour!":"Hastes e relâmpagos — um Estalador. Ele adora blindagem!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalia! O chão tremula de calor — um Braseiro!",
"Careful, a Brazier underfoot!":"Cuidado, um Braseiro sob os pés!",
"Anomaly — green mist! Acid, hold your breath!":"Anomalia — névoa verde! Ácido, segure a respiração!",
"The mist is drifting our way, go around!":"A névoa está vindo na nossa direção, contorne!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalia! O ar parece vidro — uma Lente, ela entorta as balas!",
"Everything is warping… a Lens nearby!":"Tudo está distorcendo… uma Lente por perto!",
"Ha! An enemy walked right into the anomaly!":"Ha! Um inimigo entrou direto na anomalia!",
"Got him! Lure them into anomalies!":"Peguei! Atraia eles para as anomalias!",
"Beautiful zap! One less tin can.":"Que choque bonito! Uma lata a menos.",
"The anomaly got me!":"A anomalia me pegou!",
"Ow! Don't go in there!":"Ai! Não entre aí!",
"Discharged! It is dormant now.":"Descarregada! Agora está dormente.",
"Clear, the anomaly is discharged.":"Livre, a anomalia foi descarregada.",
"They say veins hide artifacts. Only first the vein sings…":"Dizem que os veios escondem artefatos. Só que primeiro o veio canta…",
"Throw a bolt first, then walk. Old habit.":"Jogue um parafuso primeiro, depois ande. Velho hábito.",
"throw a bolt":"jogar um parafuso",
"📦 Supply drop: landing in 4 seconds":"📦 Lançamento de suprimentos: pouso em 4 segundos",
"full magazines":"carregadores cheios",
