"Menu: pause, restart, training, graphics, settings":"Menu: pausa, reiniciar, treino, gráficos, configurações",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Tela cheia no iPhone: \"Compartilhar\" ⬆ → \"Adicionar à Tela de Início\" — o jogo abre sem as barras do Safari.",
"Open portal-meteor.pages.dev for that.":"Para isso, abra portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Toque — selecionar · toque no chão — mover · segure — menu de comandos · segure e arraste — caixa · 2 dedos — zoom",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Herói assassino: dashes com blink, katana, shurikens. Teleporta-se por zonas inimigas sozinha e despedaça robôs. 1 por lado.",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Pesquisa: desbloqueia o robô-ninja no Quartel. Requer uma fábrica de mechs concluída.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Herói (1 por lado): teleporta-se por zonas inimigas sozinha e despedaça robôs; controle-a para jogar manualmente.",
"is ready. She works on her own (AUTO) — possess her to play manually":"está pronta. Ela age sozinha (AUTO) — controle-a para jogar manualmente",
"Robo-ninja ready for action":"Robô-ninja pronta para a ação",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Inteligência: o inimigo tem um robô-ninja!",
"Warning! The enemy has a robo-ninja. Stay together":"Atenção! O inimigo tem um robô-ninja. Fique junto do grupo",
"cyber blinks":"saltos ciber",
