"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ DUELO NINJA! Bloqueie logo antes do golpe para aparar, use blink para esquivar. Fique atento ao brilho do preparo",
"The two ninjas have met in a duel!":"Os dois ninjas se encontraram em duelo!",
"⚔ Duel won! Our ninja prevails":"⚔ Duelo vencido! Nosso ninja vence",
