"ninja duel":"duelo ninja",
"POSTURE BROKEN":"POSTURA QUEBRADA",
"Teleport":"Teletransp.",
"Teleport: aim at the ground (up to 150 m)":"Teletransporte: mire no chão (até 150 m)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: ela salta pelas zonas inimigas e corta sozinha. Stick / WASD pausa por 1,5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Manual: toque em um inimigo — avanço e corte, deslize — golpe, 🛡 — bloqueio",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Manual: botão esq. — katana, botão dir. — bloqueio, Shift — salto curto, Q — shurikens, G — teletransporte",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: toque em um inimigo — avanço e corte, deslize à direita — golpe, ● — ataque, 🛡 — bloqueio (no tempo certo = aparo), ⇑ — salto curto, ✦ — shurikens, ◎ — teletransporte, AUTO — sozinha",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: botão esq. — katana (segurar — corte pesado), botão dir. — bloqueio (no tempo certo = aparo), Shift/Z — salto curto, Q — shurikens, G — teletransporte até a mira, pular no ar — pulo duplo / corrida na parede, {0} — AUTO",
"Robo-ninja: AUTO on/off":"Robô-ninja: AUTO ligado/desligado",
"Hero already deployed (1 per side)":"Herói já implantado (1 por lado)",
"Shadow protocol ready. The robo-ninja can be deployed":"Protocolo Sombra pronto. O robô-ninja pode ser implantado",
"✶ Our robo-ninja is down. Deploy her again in the Barracks":"✶ Nossa robô-ninja caiu. Implante-a novamente no Quartel",
"✶ Enemy robo-ninja destroyed!":"✶ Robô-ninja inimiga destruída!",
"Enemy robo-ninja destroyed":"Robô-ninja inimiga destruída",
"LUNGE — dodge!":"INVESTIDA — desvie!",
