"Prettier world: detailed 3D models — the Jackal and the Rhino tank on the plains, sandbag walls, concrete blocks and supply crates at capture points, rare Singing Vein crystals.":"Mundo mais bonito: modelos 3D detalhados — o Chacal e o tanque Rinoceronte nas planícies, muros de sacos de areia, blocos de concreto e caixas de suprimentos nos pontos de captura, cristais raros do Veio Cantante.",
