"Acting on their own now. Press (O) to take manual control.":"Agora agem por conta própria. Pressione (O) para assumir o controle manual.",
"Obeying only you now. Press (O) to let them act on their own, like under the AI strategist.":"Agora obedecem só a você. Pressione (O) para que ajam por conta própria, como sob o estrategista IA.",
"Grenade: hold \"Grenade\" to see the arc and blast circle; drag to aim; release to throw.":"Granada: segure \"Granada\" para ver o arco",
"Enemy vehicle or structure nearby — tap ➶ \"Rocket\".":"Veículo ou estrutura inimiga por perto — toque em ➶ \"Foguete\".",
"Enemies are bunched up — hold \"Grenade\", drag to aim, release.":"Os inimigos estão agrupados — segure \"Granada\", arraste para mirar e solte.",
