"Aim at the enemy cluster and tap ☄ \"Strike\".":"Mire no grupo de inimigos e toque em ☄ \"Ataque\".",
"Targets are far — ⇄ \"Weapon\": the railgun is stronger at range.":"Os alvos estão longe — ⇄ \"Arma\": o canhão de trilho é mais forte à distância.",
"You have a temporary heavy MG — ⇄ \"Weapon\".":"Você tem uma metralhadora pesada temporária — ⇄ \"Arma\".",
"One of our tanks is close — walk up and tap ⏏ \"Enter\".":"Um dos nossos tanques está perto — aproxime-se e toque em ⏏ \"Entrar\".",
"Man the turret — walk up and tap ⏏ \"Enter\".":"Assuma a torreta — aproxime-se e toque em ⏏ \"Entrar\".",
"It is quiet here — ⇆ at the top right switches to a unit closer to the fight.":"Está calmo aqui — ⇆ no canto superior direito troca para uma unidade mais perto da luta.",
"Reload early while no enemies are around — ⟳.":"Recarregue cedo enquanto não houver inimigos por perto — ⟳.",
"The objective is far — ☰ → ⇲ \"Redeploy\": drop pod straight to it.":"O objetivo está longe — ☰ → ⇲ \"Reposicionar\": cápsula direto até ele.",
"In the air, ☰ → ⤓ is the jet brake.":"No ar, ☰ → ⤓ é o freio a jato.",
"Tap a squad to select it, long-tap the ground or an enemy to order.":"Toque em um esquadrão para selecioná-lo; toque e segure o chão ou um inimigo para dar uma ordem.",
"Long-tap the ground — rally point for new troops.":"Toque e segure o chão — ponto de encontro para novas tropas.",
"Only builders build: \"⚒ Builder\" on the right → building → spot → \"✔ Build\".":"Só engenheiros constroem: \"⚒ Engenheiro\" à direita → construção → local → \"✔ Construir\".",
"Tap \"ORE\" at the top left — where ore comes from.":"Toque em \"MINÉRIO\" no canto superior esquerdo — de onde vem o minério.",
"Tank: 💥 \"Barrage\", ☁ \"Smoke\", ⏩ \"Boost\", ⏏ \"Exit\".":"Tanque: 💥 \"Barragem\", ☁ \"Fumaça\", ⏩ \"Impulso\", ⏏ \"Sair\".",
"Plenty of targets — 💥 \"Barrage\".":"Muitos alvos — 💥 \"Barragem\".",
"Drone: ⤒ / ⤓ — up / down, ➤ \"Ram\" your aim point.":"Drone: ⤒ / ⤓ — subir / descer, ➤ \"Colidir\" com seu ponto de mira.",
