"Tank: 💥 \"Barrage\", ☁ \"Smoke\", ⏩ \"Boost\", ⚙ \"Repair kit\", ⏏ \"Exit\".":"Tanque: 💥 \"Barragem\", ☁ \"Fumaça\", ⏩ \"Turbo\", ⚙ \"Kit de reparo\", ⏏ \"Sair\".",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Veículo ou estrutura inimiga por perto — toque nele: um foguete é lançado.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Muitos inimigos — toque duas vezes num espaço vazio à direita: o reflexo desacelera o tempo.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Mire no grupo de inimigos e toque 3 vezes — ataque de artilharia.",
