"Split-screen cinema, no core or tunnels, troopers build, strategist marks, caches, crawling, developer menu":"Cinema em tela dividida, sem núcleo nem túneis, soldados constroem, estrategista marca, esconderijos, rastejar, menu do desenvolvedor",
"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"Três modos de manche para celular, estratégia simples, assento de artilheiro no veículo, terreno de cânions, classes de esquadrão, explosivos",
