"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Facções Consórcio / Enxame com escolha antes da partida, crateras de explosão, visão em terceira pessoa",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomalias (o \"Veio Cantante\" e mais 5), descarga com um virote ou granada, artefatos, chamadas de apoio por PC, caixas de suprimentos",
