"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Saída fácil do núcleo: Space — para o poço, B — cápsula para a superfície; efeitos de habilidades são resetados ao morrer",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Progressão sem fim: generais e Marechal ★, níveis de carreira, maestria de armas e acessórios, medalhas, contratos diários — tela Carreira",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Estratégia: zoom suave com a roda, ícones e rótulos de unidades (Alt — todas), painel Tropas / Edifícios à esquerda",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"botão dir. — atacar movendo, botão dir. duplo — marchar atirando; ordens raras em \"Mais ordens ▾\"; sem botões duplicados",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Armas de nível Atirador: balas hitscan, rifle de 720 RPM, metralhadora, recuo, mira com botão dir., carregadores e recarga com R, marcadores de acerto",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Gravidade mais pesada, jetpack mais responsivo, avanço com Z ou jato duplo no ar; a arma não voa mais junto ao trocar de unidade",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Engenheiros: selecione um engenheiro, escolha uma construção, posicione uma planta; Extratores em veios de minério; clique em \"MINÉRIO\" para ver a renda e como aumentá-la",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Botões cinzas explicam o motivo e oferecem uma solução; botões maiores, faixa \"Em andamento\", \"▶ Controlar\", Tab é a única tecla de modo",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Câmera de estratégia sem saltos ou giros, zoom no cursor, minimapa arrastável",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Novos veículos: invasor Chacal, lança-foguetes Grad (foguetes teleguiados), morteiro Martelo; o Enxame ganha Vespa, Colmeia, Trebuchet",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"O estrategista IA mantém as ordens e para de spam de voz; as batalhas vêm até você; B — reposicionar, Shift+B — para a luta; bússola, H — qual alvo",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Jogo livre (K) e modo solo (J), predefinições F2; Esc pausa e retoma; saves: slots, exportar e importar",
