"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"בחר פלג לפני משחק: \"הקונסורציום\" (חיל רגלים כבד בשריון ממונע, שריון וארטילריה) או \"הנחיל\" (מהירות, להקות רחפנים, ירי כבד עם עיוות). ה-AI משחק בפלג השני. הבחירה נשמרת.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"לכל פלג יש כלי רכב ופריטים ייחודיים משלו: הקונסורציום — טנק \"קרנף\" ו\"לוחות קרמיט\", הנחיל — \"להקת רחפנים\" ו\"תרמילי סילון פאזה\". האיזון נבדק במשחקי בוטים.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"מכתשי פיצוץ: ארטילריה, רקטות ותותחי טנקים חופרים בורות במטאור — אפשר ללכת ולנסוע דרכם ולהתגונן בתוכם.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"מבט גוף שלישי ללוחמים (V, נשמר; בטלפון — בקרים) ומצלמת רכב חלקה עם סימן לאן יפגע התותח.",
