"Supply drop":"הצנחת אספקה",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"מצנח ארגז ליד הכוחות שלך: תחמושת, רימונים, רקטות, חלקי נשק, ערכת תיקון.",
"\"Grad\" rocket strike":"מטח רקטות \"גראד\"",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"‏16 רקטות על שטח רחב אחרי 3 שניות — מהיר ורחב יותר מארטילריה.",
"WARNING: Swarm \"Grad\" incoming on your area!":"אזהרה: \"גראד\" של הנחיל בדרך לאזורך!",
"Warning! Rocket salvo on our position!":"אזהרה! מטח רקטות על עמדתנו!",
"take the supply crate":"קח את ארגז האספקה",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"אנומליות על המטאור (גל 1): \"העורק המזמר\" — גביש ירוק זוהר שמזמזם ופוגע בכל מי שבקרבתו בפולסים קצביים; \"מערבולת\" מושכת ומרסקת, \"מפצפץ\" יוצר קשתות חשמל בין מוטות, \"אח גחלים\" פורץ בלהבות מתחת לרגליים, ו\"ערפל חומצי\" ו\"עדשה\" (מעקמת כדורים ואת שדה הראייה שלך) נסחפים סביב.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"אפשר לחוש אנומליות מראש (זמזום, זוהר, ערפל חום). פרוק אחת ברימון, ברקטה או בבורג (E לידה): היא תהפוך לרדומה ולעיתים תותיר ארטיפקט עם יתרון וחיסרון. החוליה שלך מזהירה ברדיו, ולפעמים אויבים (וגם חברים) נכנסים בטעות — משוך אותם!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"תמיכה בנקודות פיקוד: 4 בקרב (📡 בטלפון) — הצנחת אספקה, סריקת סיור, מטח רקטות \"גראד\", ארטילריה בכוונת. האסטרטג רואה אנומליות במפה רק לאחר סריקה.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"ארגזי אספקה בהריסות של משלחות ישנות",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"‏v7.7 נשארת בתפריט \"🕘 גרסת המשחק\". אפשר לכבות את האנומליות בהגדרות.",
