"⚒ Builders: {0} · LMB on ground — place, Shift — several · RMB on own — repair/help":"‏⚒ מהנדסים: {0} · לחצן שמאלי על הקרקע — הצבה, Shift — כמה · לחצן ימני על שלך — תיקון/עזרה",
"Cancel and refund":"ביטול והחזר",
"Buildings are built by <b>builders</b>: pick a building → LMB on a spot. The selected or nearest idle builder goes. <kbd>.</kbd> — idle builder.":"מבנים נבנים על ידי <b>מהנדסים</b>: בחר מבנה ← לחצן שמאלי על מקום. המהנדס שנבחר או הפנוי הקרוב ביותר יגיע. <kbd>.</kbd> — מהנדס פנוי.",
"Train a builder at the HQ/outpost":"אמן מהנדס במפקדה/במוצב",
"HQ — refining":"מפקדה — זיקוק",
"always on while the HQ or an outpost stands":"פעיל תמיד כל עוד המפקדה או מוצב עומדים",
"Extractors on veins":"מחלצים על עורקים",
"+{0}/min each{1} — watch the \"+N\"":"‏+{0}/min כל אחד{1} — שים לב ל-\"+N\"",
"Captured points":"נקודות שנכבשו",
"+{0}/min per point":"‏+{0}/min לכל נקודה",
"Tap a spot on the ground first":"קודם הקש על מקום על הקרקע",
"tap a spot":"הקש על מקום",
"H":"מ",
"N":"צ",
"E":"מז",
"S":"ד",
"W":"מע",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"‏\"▶ שחק עכשיו\" — הכפתור הראשון בתפריט: טיסה קצרה מתחת לשמי הפורטל וישר לקרב (דלג בכל מקש או בהקשה).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"פגיעות מרגישות כמו פגיעות: צליל מתכתי וניצוצות, סמן חיסול בכוונת (ירי בראש — צהוב), רצף ×N, רעידה חלקה מפיצוצים, הילוך איטי בחיסולים מכריעים. אפשר לכבות את הרעידה, ההילוך האיטי והרמז בהגדרות.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"תוצאות המשחק: זמן, חיסולים, הרצף הטוב ביותר, ★ MVP והחוליה הטובה ביותר, כרטיס משחק — \"⇪ שתף\", PNG או קישור למשחק.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"רמז \"מה לעשות עכשיו\" משמאל מתחת למשאבים: פקודת אסטרטג ה-AI, נקודה לכיבוש, מתקפת הנחיל. ✕ או F7 — כיווץ.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"הקרב נשמר מעצמו כשסוגרים או מסתירים את הלשונית — \"⟲ המשך\" בתפריט.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"‏v7.5 נשארת בתפריט \"🕘 גרסת המשחק\" למקרה שתעדיף אותה. כעת נשלחות סטטיסטיקות אנונימיות (ללא שמות או אימייל); אפשר לכבות בהגדרות.",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"‏☰ בפינה פותח את תפריט ההשהיה: המשך, התחל מחדש, אימון, גרפיקה, הגדרות, תפריט ראשי (באישור). טלפון: ☰ למעלה מימין (פעולות קרב — האריח \"⚡ פעולות\"); מחשב: הכפתור \"☰ תפריט\" למעלה מימין או Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"הגרפיקה תמיד רגילה כברירת מחדל — Dendy רק אם תבחר בה: המתג \"גרפיקה: רגילה / Dendy (8 ביט) / 16 ביט\" נמצא בתפריט הראשי ובתפריט ההשהיה. אם המשחק מגמגם מאוד, תופיע הצעה עם כפתור \"הפעל Dendy\".",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"טלפון וטאבלט: כפתור הפעולה \"✋\" מימין מופיע רק כשיש מה לעשות בקרבת מקום — \"קח\" (מטמון, ארגז), \"עלה\" (רכב, צריח, תותח), \"בנה\", \"רד\", \"בורג\" ליד אנומליה. אפשר גם פשוט להקיש על האובייקט המודגש.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"טלפון, אסטרטגיה: החזק אצבע ~0.3 שנ' (הטלפון רוטט ומופיעה טבעת צהובה) וגרור — תיבת בחירה; החלקה רגילה מזיזה את המצלמה. יש גם כפתור \"תיבה\" בצד ימין; באימון, שלב \"תיבה\" מקבל גם הקשה על חוליה.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"טלפון: קל יותר לפגוע בכפתורים הקטנים, רשימת התמיכה 📡 גדולה יותר, ולוחות האסטרטגיה כבר לא מסתירים את מסכי ההשהיה והתוצאות. v7.8 נשארת בתפריט \"🕘 גרסת המשחק\".",
"Lagging? Try the Dendy graphics — they are lighter.":"האטה? נסו את גרפיקת Dendy — היא קלה יותר.",
