"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"תפריט ☰ בטלפון ובמחשב, בלי Dendy אוטומטי, כפתור \"✋\" במגע, בחירה במסגרת בטלפון",
