"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Barmoqni yerga ~0,3 soniya bosib turing — telefon tebranadi va sariq halqa paydo boʻladi — soʻng barmoqni koʻtarmasdan suring: tanlash ramkasi chiqadi. Yoki oʻngdagi \"Ramka\" tugmasidan foydalaning. Otryadga oddiygina bosish ham ishlaydi.",
