"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Keyin yerga bosing (tegining): ular harakatlanadi va yoʻlda jang qiladi. Dushmanga bosilsa — hujum qiladi. Oʻng tugma bilan bir xil.",
"Run":"Yugurish",
"Then click (tap) the ground: they run without engaging. Same as double RMB.":"Keyin yerga bosing (tegining): ular jang qilmasdan yuguradi. Oʻng tugmani ikki marta bosish bilan bir xil.",
"2×RMB":"2×oʻng tugma",
"Selected groups stay put and return fire.":"Tanlangan guruhlar joyida turadi va javob oʻti ochadi.",
"Run back to the HQ (or nearest outpost) without engaging.":"Jang qilmay shtabga (yoki eng yaqin forpostga) qaytib yuguring.",
"Squads jet up through the dome portal and land at the enemy.":"Otryadlar gumbaz portali orqali uchib chiqib, dushman yonida qoʻnadi.",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Tanlangan jangchi, tank yoki turelni oʻzingiz boshqaring. Jangda xuddi shu tugma sizni strategiyaga qaytaradi.",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"4 jangchi: hujumchi, ogʻir pulemyotchi, raketachi, vrach.",
"Autonomous combat vehicle: cannon and MG, barrage, smoke, overdrive.":"Avtonom jangovar mashina: toʻp va pulemyot, ogʻir oʻt, tutun, forsaj.",
"Fast flying gunner, good against infantry.":"Tez uchuvchi oʻqchi, piyodalarga qarshi yaxshi.",
"Elite squad with strong jetpacks — can sky-assault through the dome.":"Kuchli ranetli elita otryad — gumbaz orqali havodan hujum qila oladi.",
"A lone railgun sniper.":"Yolgʻiz relsotronli snayper.",
"Fast scout: sees far and spots enemies.":"Tez razvedkachi: uzoqni koʻradi va dushmanlarni aniqlaydi.",
"A squad drops from orbit right at the front line.":"Otryad orbitadan toʻgʻridan-toʻgʻri front chizigʻiga tushadi.",
"Jetpacks II: infantry reaches the dome and can sky-assault.":"Ranetlar II: piyoda askar gumbazga yetib, havodan hujum qila oladi.",
