"the gamepad view button or ":"geympad koʻrinish tugmasi yoki ",
"Commander mode, faction bosses, living meteor (terrain, biomes, weather, anomalies, fauna), living world; faster, gamepad, tablet, encyclopedia, feedback mode, simple phone interface":"Komandir rejimi, fraksiya boshliqlari, tirik meteor (relyef, biomlar, ob-havo, anomaliyalar, fauna), tirik dunyo; tezroq, geympad, planshet, ensiklopediya, fikr-mulohaza rejimi, telefon uchun oddiy interfeys",
"Fixes: the camera card hides under pause and menus, building labels are smaller and fainter, clean screen (F9/👁) also hides world markers.":"Tuzatishlar: kamera kartochkasi pauza va menyularda yashiriladi, bino yorliqlari kichikroq va xiraroq, toza ekran (F9/👁) dunyo belgilarini ham yashiradi.",
"Prettier world: detailed 3D models — the Jackal and the Rhino tank on the plains, sandbag walls, concrete blocks and supply crates at capture points, rare Singing Vein crystals.":"Goʻzalroq dunyo: batafsil 3D modellar — tekisliklardagi Chiyaboʻri va Karkidon tanki, qum xaltalaridan devorlar, egallash nuqtalaridagi beton bloklar va taʼminot qutilari, noyob Kuylovchi tomir kristallari.",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Battlefielddagi kabi sevimli sinf (U, oʻlimdan keyin raqamlar): mavjud boʻlganda shu sinfda qayta tugʻilasiz",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Texnika birinchi shaxsdan (V — tashqi/kabina); yumshoq nishonga olish yordami — Sozlamalarda",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Yadrodan oson chiqish: Space — shaxtaga, B — kapsula bilan yer yuziga; qobiliyat effektlari oʻlganda nolga tushadi",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Cheksiz rivojlanish: generallar va Marshal ★, karyera darajalari, qurol mahorati va jihozlar, medallar, kundalik shartnomalar — Karyera ekrani",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategiya: gʻildirak bilan silliq zoom, birlik belgilari va yozuvlari (Alt — hammasi), chapda Qoʻshin / Binolar paneli",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"oʻng tugma — hujum bilan yurish, qoʻsh oʻng tugma — yurib otish; kam ishlatiladigan buyruqlar \"Boshqa buyruqlar ▾\" ichida; takroriy tugmalar yoʻq",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Otuvchi darajasidagi qurollar: hitscan oʻqlar, 720 RPM miltiq, pulemyot, qaytish zarbasi, oʻng tugma bilan nishon olish, magazinlar va R bilan qayta zaryadlash, zarba belgilari",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Ogʻirroq gravitatsiya, sezgir ranets, Z bilan tezlanish yoki havoda ikki marta ranets; birlik almashtirilganda qurol endi birga uchib ketmaydi",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Muhandislar: muhandisni tanlang, bino tanlang, chizmani joylashtiring; Ekstraktorlar ruda tomirlarida; daromadni va uni oshirish yoʻlini koʻrish uchun \"RUDA\" ni bosing",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Kulrang tugmalar sababini tushuntiradi va yechim taklif qiladi; kattaroq tugmalar, \"Jarayonda\" tasmasi, \"▶ Boshqarish\", Tab — yagona rejim tugmasi",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Sakrashlar va aylanishlarsiz strategiya kamerasi, kursor tomon zoom, sudrab boʻladigan minixarita",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Yangi texnika: Chiyaboʻri reyder, Grad RSZO (yoʻnaltiriladigan raketalar), Bolgʻa minomyot; Gala Ari, Uya, Manjaniq oladi",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"AI-strateg buyruqlarni saqlaydi va ovozli spamni toʻxtatadi; janglar oʻzingiz tomon keladi; B — qayta joylashtirish, Shift+B — jangga; kompas, H — qaysi nishon",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Erkin oʻyin (K) va yakka oʻynash (J), F2 presetlar; Esc pauza qiladi va davom ettiradi; saqlashlar: slotlar, eksport va import",
