"Cancel and refund":"Бекор кардан ва баргардонидан",
"Buildings are built by <b>builders</b>: pick a building → LMB on a spot. The selected or nearest idle builder goes. <kbd>.</kbd> — idle builder.":"Биноҳоро <b>муҳандисон</b> месозанд: бино интихоб кунед → тугмаи чап ба ҷой. Муҳандиси интихобшуда ё наздиктарини бекор меравад. <kbd>.</kbd> — муҳандиси бекор.",
"Train a builder at the HQ/outpost":"Дар ситод/посгоҳ муҳандис тайёр кунед",
"HQ — refining":"Ситод — коркард",
"always on while the HQ or an outpost stands":"то даме ки ситод ё посгоҳ истодааст, ҳамеша фаъол аст",
