"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ Ҳозир бозӣ кардан\" — тугмаи аввали меню: парвози кӯтоҳ дар зери осмони портал ва якбора ба ҷанг (бо ягон клавиша ё ламс гузаред).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Зарбаҳо воқеӣ ҳис мешаванд: садои металлӣ ва шарораҳо, нишони кушторкунӣ дар нишонгир (тир ба сар — зард), силсилаи ×N, ларзиши мулоим аз таркишҳо, ҳаракати суст дар куштори муҳим. Ларзиш, ҳаракати суст ва маслиҳатро дар Танзимот хомӯш кардан мумкин аст.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Натиҷаҳои бозӣ: вақт, куштор, беҳтарин силсила, ★ MVP ва беҳтарин даста, корти бозӣ — \"⇪ Мубодила\", PNG ё истинод ба бозӣ.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Маслиҳати \"ҳозир чӣ кор кардан лозим\" дар тарафи чап, зери захираҳо: фармони AI-стратег, нуқтаи забткарданӣ, ҳамлаи Гала. ✕ ё F7 — ҷамъ кардан.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Ҳангоми пӯшидан ё пинҳон кардани варақа ҷанг худаш захира мешавад — дар меню \"⟲ Идома додан\".",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 дар менюи \"🕘 Версияи бозӣ\" мемонад, агар онро авлотар донед. Акнун омори беном (бе ном ва почтаи электронӣ) фиристода мешавад; дар Танзимот хомӯш кардан мумкин аст.",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ дар кунҷ менюи таваққуфро мекушояд: Идома додан, Аз нав оғоз кардан, Омӯзиш, Графика, Танзимот, Менюи асосӣ (бо тасдиқ). Телефон: ☰ боло дар тарафи рост (амалҳои ҷангӣ — плитаи \"⚡ Амалҳо\"); компютер: тугмаи \"☰ Меню\" боло дар рост ё Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Графика ба таври пешфарз ҳамеша муқаррарӣ аст — Dendy танҳо агар шумо интихоб кунед: тугмачаи \"Графика: Муқаррарӣ / Dendy (8 бит) / 16 бит\" дар менюи асосӣ ва менюи таваққуф ҷойгир аст. Агар бозӣ сахт суст шавад, маслиҳат бо тугмаи \"Dendy-ро фаъол кунед\" пайдо мешавад.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Телефон ва планшет: тугмаи амали \"✋\" дар тарафи рост танҳо вақте пайдо мешавад, ки дар наздикӣ коре бошад — \"Гирифтан\" (анбор, сандуқ), \"Нишастан\" (нақлиёт, турел, тӯп), \"Сохтан\", \"",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Дар телефон, стратегия: ангуштро тақрибан 0,3 сония нигоҳ доред (телефон меларзад, ҳалқаи зард пайдо мешавад) ва кашед — қуттии интихоб; ҳаракати оддӣ камераро мекӯчонад. Дар тарафи рост тугмаи «Қуттӣ» низ ҳаст; дар таълим қадами «Қуттӣ» ламс кардани дастаро низ қабул мекунад.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Телефон: ба тугмаҳои хурд расидан осонтар шуд, рӯйхати дастгирии 📡 калонтар аст, панелҳои стратегия дигар экранҳои таваққуф ва натиҷаҳоро намепӯшонанд. v7.8 дар менюи «🕘 Версияи бозӣ» мемонад.",
"Lagging? Try the Dendy graphics — they are lighter.":"Суст кор мекунад? Графикаи Dendy-ро санҷед — он сабуктар аст.",
