"Commander — still in development":"Фармондеҳ — ҳанӯз дар таҳия",
"Pause: resume, restart, training, graphics, settings, main menu":"Таваққуф: идома, аз нав оғоз, машқ, графика, танзимот, менюи асосӣ",
"Menu: pause, restart, training, graphics, settings":"Меню: таваққуф, аз нав оғоз, машқ, графика, танзимот",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Экрани пурра дар iPhone: «Мубодила» ⬆ → «Илова ба экрани асосӣ» — бозӣ бе панелҳои Safari кушода мешавад.",
"Open portal-meteor.pages.dev for that.":"Барои ин portal-meteor.pages.dev-ро кушоед.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Ламс — интихоб · ламс ба замин — ҳаракат · нигоҳ доштан — менюи фармон · нигоҳ дошта кашидан — чорчӯба · 2 ангушт — тағйири андоза",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Қаҳрамони қотил: ҷаҳишҳои фаврӣ, катана, шурикенҳо. Худаш аз минтақаҳои душман телепорт мешавад ва роботҳоро пора мекунад. Барои ҳар тараф 1 адад.",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Таҳқиқ: робо-нинҷаро дар Казарма кушода мекунад. Заводи Mech-и сохташуда лозим аст.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Қаҳрамон (барои ҳар тараф 1): худаш аз минтақаҳои душман телепорт мешавад ва роботҳоро пора мекунад; барои дастӣ бозӣ кардан ӯро идора кунед.",
"is ready. She works on her own (AUTO) — possess her to play manually":"омода аст. Вай худаш амал мекунад (AUTO) — барои дастӣ бозӣ кардан ӯро идора кунед",
"Robo-ninja ready for action":"Робо-нинҷа ба амал омода аст",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Иттилоот: душман робо-нинҷа дорад!",
"Warning! The enemy has a robo-ninja. Stay together":"Ҳушдор! Душман робо-нинҷа дорад. Бо ҳам бошед",
"cyber blinks":"киберҷаҳишҳо",
"Too far for a dash — get closer or teleport":"Барои ҷаҳиш хеле дур аст — наздиктар шавед ё телепорт кунед",
"enemy group":"гурӯҳи душман",
"order":"фармон",
"nearby":"наздик",
"Zone cleared":"Минтақа тоза шуд",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ ДУЭЛИ НИНҶАҲО! Дарҳол пеш аз зарба банд кунед, то дафъ шавад, бо ҷаҳиш гурезед. Ба дурахши омодагӣ диққат диҳед",
"The two ninjas have met in a duel!":"Ду нинҷа дар дуэл вохӯрданд!",
"⚔ Duel won! Our ninja prevails":"⚔ Дуэл бурд шуд! Нинҷаи мо ғолиб омад",
"⚔ Duel lost…":"⚔ Дуэл бохта шуд…",
"ninja duel":"дуэли нинҷа",
