"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: вай дар минтақаҳои душман ҷаҳида, худаш мебурад. Стик / WASD онро барои 1,5 сония таваққуф мекунад",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Дастӣ: ба душман ламс кунед — ҷаҳиш ва бурриш, кашед — зарба, 🛡 — муҳофизат",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Дастӣ: тугмаи чап — катана, тугмаи рост — муҳофизат, Shift — ҷаҳиши кутоҳ, Q — сюрикенҳо, G — телепорт",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Нинҷа: ба душман ламс кунед — ҷаҳиш ва бурриш, дар тарафи рост кашед — зарба, ● — задан, 🛡 — муҳофизат (дар лаҳзаи дуруст = дафъ), ⇑ — ҷаҳиши кутоҳ, ✦ — сюрикенҳо, ◎ — телепорт, AUTO — худаш",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Нинҷа: тугмаи чап — катана (нигоҳ доштан — зарбаи вазнин), тугмаи рост — муҳофизат (дар лаҳзаи дуруст = дафъ), Shift/Z — ҷаҳиши кутоҳ, Q — сюрикенҳо, G — телепорт ба нишонгоҳ, ҷаҳидан дар ҳаво — ҷаҳиши дучанд / давидан дар девор, {0} — AUTO",
"Robo-ninja: AUTO on/off":"Робо-нинҷа: АВТО фаъол/хомӯш",
