"Shadow protocol ready. The robo-ninja can be deployed":"Протоколи Соя омода аст. Робо-нинҷаро ҷойгир кардан мумкин",
"✶ Our robo-ninja is down. Deploy her again in the Barracks":"✶ Робо-нинҷаи мо афтод. Ӯро дар Казарма аз нав ҷойгир кунед",
