"LMB — strike (hold — heavy) · RMB — block · Shift — blink · Q — shurikens · G — teleport":"тугмаи чап — зарба (нигоҳ доред — сангин) · тугмаи рост — манъ · Shift — ҷаҳиш · Q — сюрикенҳо · G — телепорт",
