"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Ҷанговар, танк ё турели интихобшударо худатон идора кунед. Ҳамин тугма дар набард шуморо ба стратегия бармегардонад.",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"4 ҷанговар: ҳамлавар, тирандози вазнин, мушакандоз, табиб.",
"Autonomous combat vehicle: cannon and MG, barrage, smoke, overdrive.":"Мошини ҷангии мустақил: тӯп ва пулемёт, борони оташ, дуд, афзудани иқтидор.",
"Fast flying gunner, good against infantry.":"Тирандози парвозкунандаи тез, бар зидди пиёдагард хуб.",
"Elite squad with strong jetpacks — can sky-assault through the dome.":"Дастаи элитӣ бо ранецҳои тавоно — метавонад тавассути гунбаз аз ҳаво ҳамла кунад.",
"A lone railgun sniper.":"Снайперчии танҳо бо рейлган.",
