"Top view: build, order troops, give orders. The same key in strategy possesses the selected unit.":"Намои боло: сохтан, фармоиш додани сарбозон, фармон додан. Дар стратегия ҳамин тугма воҳиди интихобшударо идора мекунад.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"менюи ☰ дар телефон ва компютер, бе Dendy-и худкор, тугмаи «✋» дар сенсор, интихоби қуттӣ дар телефон",
"16-bit":"16-bit",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Робо-нинҷа, радиои EDMITRY, забонҳои узбекӣ ва тоҷикӣ, UX барои телефон ва iPhone",
