"the gamepad view button or ":"тугмаи намои геймпад ё ",
"Commander mode, faction bosses, living meteor (terrain, biomes, weather, anomalies, fauna), living world; faster, gamepad, tablet, encyclopedia, feedback mode, simple phone interface":"ҳолати Фармондеҳ, саркардаҳои гурӯҳҳо, метеори зинда (релеф, биомҳо, обу ҳаво, аномалияҳо, фауна), олами зинда; тезтар, геймпад, планшет, энсиклопедия, ҳолати фикру мулоҳиза, интерфейси оддии телефон",
"Fixes: the camera card hides under pause and menus, building labels are smaller and fainter, clean screen (F9/👁) also hides world markers.":"Ислоҳҳо: корти камера ҳангоми таваққуф ва менюҳо пинҳон мешавад, нишонаҳои бино хурдтар ва тираянд, экрани тоза (F9/👁) нишонаҳои оламро низ пинҳон мекунад.",
"Prettier world: detailed 3D models — the Jackal and the Rhino tank on the plains, sandbag walls, concrete blocks and supply crates at capture points, rare Singing Vein crystals.":"Ҷаҳони зеботар: моделҳои муфассали 3D — Шағол ва танки Каркадан дар дашт, деворҳои ҳалтаҳои рег, блокҳои бетонӣ ва қуттиҳои таъминот дар нуқтаҳои забт, кристаллҳои нодири Раги Сароянда.",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Синфи дӯстдошта мисли Battlefield (U, рақамҳо баъд аз марг): дар сурати имкон бо он аз нав пайдо мешавӣ",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Техника аз шахси аввал (V — берун/кабина); ёрии мулоими нишонгирӣ — дар Танзимот",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Баромадани осон аз ядро: Space — ба шахта, B — капсула ба сатҳ; таъсири қобилиятҳо ҳангоми марг аз нав танзим мешаванд",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Пешрафти бепоён: генералҳо ва Маршал ★, сатҳҳои касб, маҳорати силоҳ ва замимаҳо, медалҳо, шартномаҳои рӯзона — экрани Касб",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Стратегия: тағйири ҳаҷми ҳамвор бо чархак, нишонаҳо ва навиштаҷоти воҳидҳо (Alt — ҳама), панели Қушунҳо / Биноҳо дар тарафи чап",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"тугмаи рост — ҳамла ҳангоми ҳаракат, дубора тугмаи рост — роҳ рафтан бо оташкушоӣ; фармонҳои нодир дар «Фармонҳои дигар ▾»; тугмаҳои такрорӣ нест",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Силоҳҳои сатҳи Тирандоз: тирҳои hitscan, милтиқи 720 RPM, пулемёт, зарбаи бозгашт, нишонгирӣ бо тугмаи рост, мағозаҳо ва аз нав пур кардан бо R, нишонаҳои расидан",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Ҷозиба вазнинтар, ранеци ҷавобгӯ, шитоб бо Z ё дукаратаи ранец дар ҳаво; ҳангоми иваз кардани воҳид силоҳ дигар бо он намепарад",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Муҳандисҳо: муҳандисро интихоб кун, бино интихоб кун, нақшаро гузор; Экстракторҳо дар рагҳои маъдан; барои дидани даромад ва роҳи афзудани он «МАЪДАН»-ро пахш кун",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Тугмаҳои хокистарӣ сабабро шарҳ медиҳанд ва роҳи ҳал пешниҳод мекунанд; тугмаҳои калонтар, навори «Дар ҷараён», «▶ Идора», Tab — калиди ягонаи ҳолат",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Камераи стратегӣ бе ҷаҳиш ва чархзанӣ, зум ба самти курсор, харитаи хурди кашидашаванда",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Техникаи нав: рейдери Шағол, РСЗО Град (мушакҳои худҳидоятшаванда), миномёти Болға; Гала Занбӯр, Кандӯ, Манҷаниқ мегирад",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"AI-стратег фармонҳоро нигоҳ медорад ва спами овозиро қатъ мекунад; задухӯрдҳо ба назди ту меоянд; B — аз нав ҷойгир кардан, Shift+B — ба задухӯрд; қутбнамо, H — кадом ҳадаф",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Бозии озод (K) ва танҳо бозӣ (J), пресетҳои F2; Esc таваққуф мекунад ва идома медиҳад; захираҳо: слотҳо, содирот ва воридот",
